import{_ as l,H as i,f as a,i as p}from"./chunks/framework.BH2BK_3i.js";const u=JSON.parse('{"title":"17 | 如何设计一个面试中富有竞争力的上下文管理机制？","description":"","frontmatter":{},"headers":[{"level":2,"title":"基础面试策略","slug":"基础面试策略","link":"#基础面试策略","children":[{"level":3,"title":"第一个问题：你的 Agent 里面有什么上下文？","slug":"第一个问题-你的-agent-里面有什么上下文","link":"#第一个问题-你的-agent-里面有什么上下文","children":[]},{"level":3,"title":"第二个问题：这些内容分别怎么存？","slug":"第二个问题-这些内容分别怎么存","link":"#第二个问题-这些内容分别怎么存","children":[]},{"level":3,"title":"第三个问题：这些上下文怎么找出来？","slug":"第三个问题-这些上下文怎么找出来","link":"#第三个问题-这些上下文怎么找出来","children":[]},{"level":3,"title":"第四个问题：上下文太长了怎么办？","slug":"第四个问题-上下文太长了怎么办","link":"#第四个问题-上下文太长了怎么办","children":[]},{"level":3,"title":"第五个问题：压缩之后怎么找回细节？","slug":"第五个问题-压缩之后怎么找回细节","link":"#第五个问题-压缩之后怎么找回细节","children":[]},{"level":3,"title":"小节","slug":"小节","link":"#小节","children":[]}]},{"level":2,"title":"高级面试策略：围绕一个业务问题，设计独特机制","slug":"高级面试策略-围绕一个业务问题-设计独特机制","link":"#高级面试策略-围绕一个业务问题-设计独特机制","children":[]},{"level":2,"title":"总结","slug":"总结","link":"#总结","children":[]},{"level":2,"title":"附录","slug":"附录","link":"#附录","children":[]}],"relativePath":"AIAgent系统设计面试现场/17｜如何设计一个面试中富有竞争力的上下文管理机制？.md","filePath":"AIAgent系统设计面试现场/17｜如何设计一个面试中富有竞争力的上下文管理机制？.md","lastUpdated":1795451227000}'),t={name:"AIAgent系统设计面试现场/17｜如何设计一个面试中富有竞争力的上下文管理机制？.md"};function n(s,e,r,o,h,d){return i(),a("div",null,[...e[0]||(e[0]=[p(`<h1 id="_17-如何设计一个面试中富有竞争力的上下文管理机制" tabindex="-1">17 | 如何设计一个面试中富有竞争力的上下文管理机制？ <a class="header-anchor" href="#_17-如何设计一个面试中富有竞争力的上下文管理机制" aria-label="Permalink to &quot;17 | 如何设计一个面试中富有竞争力的上下文管理机制？&quot;">​</a></h1><p>你好，我是大明。</p><p>前面几讲，我们陆续讨论了分层上下文、上下文窗口编排、摘要压缩、细节召回、用户画像以及长任务处理。</p><p>那么现在问题来了：这些东西怎么组合起来，形成一套面试中富有竞争力的上下文管理机制？</p><p>一般来说，很多人在面试中聊到上下文管理，只能提到短期记忆、长期记忆和滑动窗口算法，比如说常见的套路就是：</p><ul><li><p>最近几轮对话直接放进 Prompt；</p></li><li><p>更早的对话做摘要；</p></li><li><p>长期记忆放进向量数据库；</p></li><li><p>用户再次提问的时候，从向量数据库里面检索几条；</p></li><li><p>如果上下文太长，就截断前面的内容。</p></li></ul><p>但是如果只有这些，无法在面试中赢得竞争优势。它的问题是，这套回答只能证明你知道上下文窗口有限，也知道向量数据库，但是无法证明你真的构建过复杂 Agent。</p><p>如果你求职的薪资比较高，那么你就更加要小心面试官的夺命连环问：</p><ul><li><p>为什么这些内容要放进窗口？</p></li><li><p>为什么另外一些内容不放？</p></li><li><p>用户的硬约束怎么保证不丢？</p></li><li><p>摘要丢掉了细节怎么办？</p></li><li><p>检索出多条互相冲突的内容怎么办？</p></li><li><p>用户今天说喜欢苹果，明天又说不喜欢苹果，你的画像怎么更新？</p></li><li><p>你怎么知道自己的上下文管理策略有效？</p></li></ul><p>所以，一套有竞争力的上下文管理机制，不能只回答“上下文存在哪里”，而要回答一个更加完整的问题，即：什么内容，应该在什么时间，以什么形式、什么粒度和什么顺序，进入当前的大模型窗口？</p><p>这才是上下文管理真正要解决的问题，也是你在面试中赢得竞争优势的关键点。</p><p>我们先来看最基础的面试策略。</p><h2 id="基础面试策略" tabindex="-1">基础面试策略 <a class="header-anchor" href="#基础面试策略" aria-label="Permalink to &quot;基础面试策略&quot;">​</a></h2><p>基础方案不需要讲得特别花哨。你只需要围绕五个问题展开：有什么、怎么存、怎么找、怎么压缩、怎么召回。</p><p>很多人在面试上下文管理的时候，上来就说：我们短期记忆放 Redis，长期记忆放向量数据库。你这样就过于简略了，毕竟一般的人就算没有做过 Agent 也能说上几句。</p><p>你的重点是围绕下面几个问题来整理你的面试方案，千万不要糊弄，不然面试官一旦问细节你的面试就挂了。</p><h3 id="第一个问题-你的-agent-里面有什么上下文" tabindex="-1">第一个问题：你的 Agent 里面有什么上下文？ <a class="header-anchor" href="#第一个问题-你的-agent-里面有什么上下文" aria-label="Permalink to &quot;第一个问题：你的 Agent 里面有什么上下文？&quot;">​</a></h3><p>你不需要像前面的章节一样，把所有 Context 分类重新介绍一遍。面试的时候，结合自己的业务，挑出最核心的几类就可以了。比如说如果你是电商 Agent，那么你可以介绍：</p><ul><li><p>当前会话和历史对话；</p></li><li><p>用户画像和商品偏好；</p></li><li><p>当前用户目标和预算约束；</p></li><li><p>商品候选集和商品知识；</p></li><li><p>当前 Plan、执行步骤和中间结果；</p></li><li><p>Action 执行结果；</p></li><li><p>用户已经确认或者否定过的关键事实。</p></li></ul><p>这里最重要的不是分类有多么专业，而是让面试官意识到你的上下文不只是聊天记录，还包括用户、任务、约束、知识、工具结果和运行状态。</p><p>有些人出去面试说到上下文，只会说有历史聊天记录，这就显得不够深入了。如果你能精心设计一个比较特殊的上下文内容，例如在社交情感类的 Agent 里面引入有关情绪相关的描述，就显得你很懂业务了。</p><h3 id="第二个问题-这些内容分别怎么存" tabindex="-1">第二个问题：这些内容分别怎么存？ <a class="header-anchor" href="#第二个问题-这些内容分别怎么存" aria-label="Permalink to &quot;第二个问题：这些内容分别怎么存？&quot;">​</a></h3><p>其实说白了，怎么存就是在内存、Redis 和持久化数据库中选两三个而已。正如之前我提到的，你大多数时候可以将短期记忆看做是长期记忆在 Redis 中的缓存，所以本质上就是你的Agent 只有上下文，没有记忆这种东西。</p><p>不过你在回答的时候可以说得高级一点，比如说回答根据内容的结构和生命周期，使用不同的存储方式。而后你再举一些例子：</p><ul><li><p>当前会话、当前任务状态放在 Redis 或运行时状态中，也会被持久化。</p></li><li><p>用户画像、关键事实、约束和任务状态放在 MySQL，也会被缓存到 Redis 中。</p></li><li><p>历史对话、Agent 输出和大型工具结果放在 ES 或向量数据库……</p></li></ul><p>你可以稍微拔高一下，即强调存储层和上下文窗口不是一回事。数据库里面可以存很多东西，但是每次调用大模型的时候，只会从里面选择一小部分内容。</p><h3 id="第三个问题-这些上下文怎么找出来" tabindex="-1">第三个问题：这些上下文怎么找出来？ <a class="header-anchor" href="#第三个问题-这些上下文怎么找出来" aria-label="Permalink to &quot;第三个问题：这些上下文怎么找出来？&quot;">​</a></h3><p>基础回答也不需要搞得特别复杂，你只需要说自己根据不同内容使用不同的查询方式：</p><ul><li><p>存内存，必然是本地缓存那种 GET 接口。</p></li><li><p>存 Redis，那差不多就是适用 Redis 的命令。</p></li><li><p>存 MySQL，基本上就是 SQL 了。例如在找用户画像的时候，大概率就是 WHERE uid =xxx 这种查询。</p></li><li><p>存 ES，要注意撰写 ES 的查询语句。在细节召回这种场景下，可能需要大模型来帮你撰写ES 查询语句，至少也要大模型来撰写召回细节的关键字。</p></li><li><p>向量数据库，类似查询 ES，都要考虑借助大模型的力量来撰写查询语句。</p></li></ul><p>但是我一般也不建议你借助通用的如 SQL 执行器之类的工具来查找，而是建议你额外进行一个封装，如图：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AIAgent%E7%B3%BB%E7%BB%9F%E8%AE%BE%E8%AE%A1%E9%9D%A2%E8%AF%95%E7%8E%B0%E5%9C%BA/images/17/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AIAgent%E7%B3%BB%E7%BB%9F%E8%AE%BE%E8%AE%A1%E9%9D%A2%E8%AF%95%E7%8E%B0%E5%9C%BA/images/17/1.png" alt=""></a></p><p>最为关键的就是，你得证明你的检索不是简单的“用户输入向量化后 Top-K”。</p><h3 id="第四个问题-上下文太长了怎么办" tabindex="-1">第四个问题：上下文太长了怎么办？ <a class="header-anchor" href="#第四个问题-上下文太长了怎么办" aria-label="Permalink to &quot;第四个问题：上下文太长了怎么办？&quot;">​</a></h3><p>基础方案里面，不需要详细讨论多级压缩算法。你只需要讲清楚两个原则。</p><p>第一个原则是，不同内容采用不同的处理方式。你可以举例子，比如说硬约束这种东西是不管你的上下文多长，都是要保留的。</p><p>第二个原则是，压缩不能一刀切。毕竟有些内容丢失只是让回答差一点，有些内容丢失则会直接导致任务失败。</p><p>你可以在面试中强调你会区分普通上下文和关键上下文。目标、硬约束、任务状态和关键证据会独立维护，不会完全依赖对话摘要。而后你在这个过程补充一下最普通的滑动窗口算法就足够了。</p><h3 id="第五个问题-压缩之后怎么找回细节" tabindex="-1">第五个问题：压缩之后怎么找回细节？ <a class="header-anchor" href="#第五个问题-压缩之后怎么找回细节" aria-label="Permalink to &quot;第五个问题：压缩之后怎么找回细节？&quot;">​</a></h3><p>这一点是基础方案里面最容易体现竞争力的地方。很多人做到摘要就结束了，你需要再往前走一步，阐明所有被压缩的内容都保留原始数据和索引。当摘要不足以支持当前推理时，可以重新召回原始细节。</p><p>而后你可以举例子说明这个点，比如说最典型的就是召回对话内容中用户提到的预算上限。当然理论上你应该在关键事实中有保留的，你还记得我说过，如果你关键事实做得好的话，大部分时候你都没啥细节要召回的。</p><h3 id="小节" tabindex="-1">小节 <a class="header-anchor" href="#小节" aria-label="Permalink to &quot;小节&quot;">​</a></h3><p>整个基础方案你可以参考这个话术来做基本介绍，后续就可以等面试官问细节了。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我们不会简单地把所有历史对话都放进 Prompt，而是会先将上下文拆成用户信息、目标和约束、任务状态、历</span></span></code></pre></div><ul><li>每次调用大模型之前，会根据当前意图和执行步骤，通过结构化查询、关键词检索和向量检索找出候选上下文，同时，摘要和压缩不会删除原始数据。当当前摘要不足以完成指代消解、事实判断或者错误定位时，会重新召回</li></ul><h2 id="高级面试策略-围绕一个业务问题-设计独特机制" tabindex="-1">高级面试策略：围绕一个业务问题，设计独特机制 <a class="header-anchor" href="#高级面试策略-围绕一个业务问题-设计独特机制" aria-label="Permalink to &quot;高级面试策略：围绕一个业务问题，设计独特机制&quot;">​</a></h2><p>记住你的面试只需要有一两个高级策略就够用了。当然你要是工作年限很高，或者带了团队，那么多用两三个也无妨。例如，你在面试中说：“我们有用户画像、分层上下文、动态筛选、动态排序、动态压缩、细节召回、RAG、多臂老虎机”，就有点像是背技术名词。</p><p>更加合适的是找到一个具体的业务难题，再围绕这个难题，把两到三个上下文机制组合起来。</p><ul><li><p>窗口动态编排：根据实时运行的情况来决定放什么以及放到什么为止</p></li><li><p>用户画像提取、适用，重点在两个地方，建模以及识别偶然的偏好变化。</p></li><li><p>长任务的解决方案，尤其是重点讨论漂移问题。在这个过程你可以混入 Plan 和 ReAct 的混合形态，再引入几个异步运行的东西，比如说摘要提取、漂移检查等。</p></li><li><p>摘要和细节召回的特殊机制：可以重点讨论你的分层摘要机制，以及配合这个机制的细节召回算法。</p></li></ul><p>我最推荐的就是这个问题：在有限上下文窗口中，如何既保留稳定的用户偏好，又适应用户临时变化，同时避免压缩后丢失关键细节？</p><p>这个问题可以自然串联起用户画像、动态上下文编排、多级压缩、细节召回这些内容。或者说，用户画像提供个性化信息，分层上下文负责组织全部信息，动态编排决定本轮放什么，差异化压缩解决窗口不足，细节召回负责找回压缩过程中丢失的内容。</p><p>这是一个可以参考的例子：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>在我们的电商 Agent 里面，用户画像不是一个简单的静态标签，而是分成当前会话、中期和长期。用户新表达</span></span>
<span class="line"><span>每次推荐之前，系统会根据当前商品品类、用户意图、Plan 步骤和剩余 Token，从不同层级画像、历史对话</span></span></code></pre></div><ul><li>如果上下文窗口比较紧张，会对不同内容采用不同压缩粒度。当前预算、硬约束和用户明确确认的偏好保留原文</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>当短期画像和长期画像冲突，或者摘要不足以解释用户当前选择时，Agent 会主动触发细节召回，从历史对话</span></span></code></pre></div><p>仅供参考，你要准备自己的故事。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>上下文有关的面试，你千万不要只谈长期记忆、短期记忆，这个东西已经没有太多竞争力了。你要做的就是在这个基础上进一步深入讨论你的上下文，要先从最基础的问题有什么、怎么存、怎么取讨论起，进而讨论怎么压缩，怎么做细节召回。</p><p>而后这些还不足，你就要考虑设计一些独特的机制，本模块讨论的比较深入的话题比如说动态编排、用户画像、长任务、分级压缩和细节召回都可以用来刷亮点。</p><p>最后，别忘了准备好话术、故事来介绍你的机制。</p><h2 id="附录" tabindex="-1">附录 <a class="header-anchor" href="#附录" aria-label="Permalink to &quot;附录&quot;">​</a></h2><p>下图是汇总了上下文管理这一章节重要知识点的知识图谱，供你回顾复习，另外我也在附件里放置了面试题和案例模版，供你学后自检。（注：附件只能在 PC 端下载，手机端不支持）</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AIAgent%E7%B3%BB%E7%BB%9F%E8%AE%BE%E8%AE%A1%E9%9D%A2%E8%AF%95%E7%8E%B0%E5%9C%BA/images/17/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AIAgent%E7%B3%BB%E7%BB%9F%E8%AE%BE%E8%AE%A1%E9%9D%A2%E8%AF%95%E7%8E%B0%E5%9C%BA/images/17/2.png" alt=""></a></p>`,62)])])}const g=l(t,[["render",n]]);export{u as __pageData,g as default};
